\label{lemma:var bound}
Let Assumptions \ref{assumption:J gradient bound} and \ref{assumption:probability lower bound} hold. Assume that $n_t$ samples are available at time $t$. Then, it holds that 
\begin{align}\label{eq:DKW 1}
\mathbb{P}\{|\hat{\nu}_t -\nu_t^\ast| >\varepsilon \} \le 2e^{-2n_t\varepsilon^2\underline{p}^2}.
\end{align}
Given a confidence level $\gamma$, for $t=1,\dots,T$, the error of the CVaR gradient estimate \eqref{eq:CVaR estimation error 1} is bounded as 
\begin{align*} 
\|e_t^1\|
 \le \frac{GL_g\sqrt{\ln (2T/\gamma)}}{\alpha_t\underline{p}\sqrt{2n_t} } 
\end{align*}
with probability $1-\gamma$.

\label{lemma:cvar-risk variation bound}
Let  $X$ be a random variable with distribution $\mathcal{D}_x$, and let  $\alpha_1, \alpha_2 \in (0,1]$ be two risk levels. Let $ |X|\leq U$. Then, we have that
\begin{align*}
    \big|{\rm{CVaR}}_{\alpha_1}[X] - {\rm{CVaR}}_{\alpha_2}[X]\big| \leq \left| \frac{1}{\alpha_1} - \frac{1}{\alpha_2} \right| U .
\end{align*}

\label{lemma:cvar-function variation bound}
Let $J_1(X)$ and $J_2(X)$ be two functions of a random variable $X$ with distribution $\mathcal{D}_x$. Then, we have that 
\begin{align*} 
        &\big|{\mathrm{CVaR}}_\alpha[J_1(X)] -{\mathrm{CVaR}}_\alpha [J_2(X)] \big| \nonumber \\ 
        \le& \frac{1}{\alpha}  \mathop{\mathbb{E}}\limits_{X\sim \mathcal{D}_x}\big[|J_1(X)-J_2(X)|\big].
    \end{align*}

\label{theorem:first-order}
Let Assumptions \ref{assumption:convex}--\ref{assumption:probability lower bound} hold.  Suppose that the total number of samples over the horizon $T$ satisfies \eqref{eq:sampling requirement} with a tuning parameter $a>0$. 
By selecting $  \eta = \left(\frac{V_\alpha+V_f}{T}\right)^{\frac{1}{3}}$, Algorithm~\ref{alg:first-order} achieves  ${\rm DR}(T) =  \tilde{\mathcal{O}}(T^{\frac{2}{3}}(V_\alpha+V_f)^{\frac{1}{3}}+ T^{1-\frac{a}{2}}) $ when $a\in(0,\frac{2}{3})$ and ${\rm DR}(T) =  \tilde{\mathcal{O}}(T^{\frac{2}{3}}(V_\alpha+V_f)^{\frac{1}{3}})$ when $a\ge \frac{2}{3}$, with high probability.

To account for the time-varying function and risk level, we partition the horizon $T$ into $s = \left\lceil\frac{T}{\Delta_T}\right\rceil$ intervals of length $\Delta_T \in (1,T)$ and examine the performance of Algorithm~\ref{alg:first-order} on each interval. Each interval is defined as
\begin{align*}
    \mathcal{T}_j  =  \big\{ t : (j-1)\Delta_T < t \le \min\{T, j\Delta_T\} \big\}, \
        {\rm for}~j = 1, \dots, s&,
\end{align*} 
where $j=\left\lceil\frac{t}{\Delta_T}\right\rceil$ denotes the interval  that time $t$ belongs to.
Denote $\tilde{x}_j^\ast$ as the optimal action over the interval $j$, i.e., $\tilde{x}_j^\ast: = \min_{x\in \mathcal{X}}\sum_{t \in \mathcal{T}_j}C_t(x)$. Then, the dynamic regret \eqref{eq:dynamic regret definition} can be written as 
\begin{align}\label{eq:DR 01}
    \mathrm{DR}(T)  &= \sum_{j=1}^s\sum_{t\in \mathcal{T}_j} \Big(\big(C_t(x_t)- C_t(\tilde{x}_j^\ast) \big) + \big( C_t(\tilde{x}_j^\ast) - C_t(x_t^\ast) \big)\Big) \nonumber \\ 
    & = \mathcal{R}_1 +  \mathcal{R}_2
\end{align}
with $\mathcal{R}_1 = \sum_{j=1}^s\sum_{t\in \mathcal{T}_j}  \big(C_t(x_t)- C_t(\tilde{x}_j^\ast) \big)$ and $\mathcal{R}_2 = \sum_{j=1}^s\sum_{t\in \mathcal{T}_j} \big( C_t(\tilde{x}_j^\ast) - C_t(x_t^\ast) \big)$. 
For $\mathcal{R}_1$, we have 
\begin{align}\label{eq:R1}
\mathcal{R}_1 &\le \sum_{j=1}^s\sum_{t\in \mathcal{T}_j} \langle \nabla_xC_t(x_t), x_t-\tilde{x}_j^\ast \rangle \nonumber \\ 
& = \sum_{j=1}^s\sum_{t\in \mathcal{T}_j} \mathbb{E}[\langle g_t^1 -e_t^1,  x_t-\tilde{x}_j^\ast \rangle ],
\end{align}
where the inequality follows from the convexity of $C_t(x)$, as shown in Lemma~\ref{lemma:cvar:convex}, and the equality from substituting \eqref{eq:CVaR estimation error 1} into \eqref{eq:R1}. 
By the gradient descent rule \eqref{eq:gradient descent}, for $t\in \mathcal{T}_j$, we have that 
\begin{flalign*}
 \|x_{t+1} - \tilde{x}_j^{\ast} \|^2  
  =   &\|\mathcal{P}_{\mathcal{X}}(x_{t}-\eta g_t^1) - \tilde{x}_j^{\ast} \|^2  \\
 \leq&  \| x_{t}-\eta g_t^1  - \tilde{x}_j^{\ast}\|^2   \\ 
=&  \|x_t-\tilde{x}_j^{\ast}\|^2+\eta^2\|g_t^1\|^2-2\eta \langle g_t^1, x_t-\tilde{x}_j^{\ast} \rangle,    &&
\end{flalign*}
where the inequality holds as $\tilde{x}_j^{\ast} \in \mathcal{X} $. 
Then, we obtain
\begin{align}\label{eq:gt-x}
  \hspace{-0.5em} \langle g_t^1, x_t-\tilde{x}_j^{\ast} \rangle \le \frac{\|x_t-\tilde{x}_j^{\ast}\|^2 -\|x_{t+1}-\tilde{x}_j^{\ast}\|^2}{2\eta} + \frac{\eta}{2}\|g_t^1\|^2,\hspace{-0.5em}
\end{align}
for $t \in \mathcal{T}_j$.
Substituting \eqref{eq:gt-x}  into $\mathcal{R}_1$, we
obtain 
\begin{align}\label{eq:R1 1}
\mathcal{R}_1   
 &\leq \sum_{j=1}^s\sum_{t\in \mathcal{T}_j} \Big( \frac{1}{2\eta} \mathbb{E}[ \|x_t-\tilde{x}_j^{\ast}\|^2 -\|x_{t+1}-\tilde{x}_j^{\ast}\|^2  ]   \nonumber \\
&\hspace{1em}+ \frac{\eta}{2}\mathbb{E}[\|g_t^1\|^2]  + \mathbb{E}[\| e_t^1\|\| x_t -\tilde{x}_j^{\ast}\| ] \Big)\nonumber  \\
&= \frac{1}{2 \eta } \sum_{j=1}^{s-1}\left( 
 \| x_{(j-1)\Delta_T+1}  -  \tilde{x}_j^{\ast}\|^2 -  \|x_{j\Delta_T} - \tilde{x}_j^{\ast}\|^2 \right) \nonumber \\
 &\hspace{1em}+ \| x_{(s-1)\Delta_T+1}  -  \tilde{x}_s^{\ast}\|^2 -  \|x_{T} - \tilde{x}_s^{\ast}\|^2+ \mathcal{R}_{11} + \mathcal{R}_{12} \nonumber \\
 &\leq \frac{D_x^2T}{ \eta\Delta_T }  + \mathcal{R}_{11} + \mathcal{R}_{12},
\end{align}
with 
$ \mathcal{R}_{11} =\sum_{t=1}^T \frac{\eta}{2}\mathbb{E}[\|g_t^1\|^2] $ and $ \mathcal{R}_{12} = \sum_{j=1}^s \sum_{t\in \mathcal{T}_j}  \mathbb{E}[\| e_t^1\|\| x_t -\tilde{x}_j^{\ast}\| ] $.
The second inequality of \eqref{eq:R1 1} follows from the diameter definition $D_x = \sup_{x,y \in \mathcal{X}} \| x-y\|$ and $\left\lceil\frac{T}{\Delta_T}\right\rceil \le \frac{2T}{\Delta_T} $. By Assumption~\ref{assumption:J gradient bound}, we have $\mathcal{R}_{11} \le \frac{\eta G^2T}{2}$.
For $\mathcal{R}_{12}$, we have 
\begin{align}\label{eq:R12}
 \mathcal{R}_{12} &\le D_x    \sum_{t=1}^T \mathbb{E}[\|e_t^1\|]   \le \frac{D_xGL_g\sqrt{\ln (2T/\gamma)}}{\sqrt{2}\alpha_{\min} \underline{p} } \sum_{t=1}^T \frac{1}{\sqrt{n_t}}  \nonumber \\ 
 &\le  \frac{c D_x G L_g\sqrt{\ln{(2T/\gamma)}}}{\sqrt{2}\alpha_{\min} \underline{p} }  T^{1-\frac{a}{2}}
\end{align}
with probability $1-\gamma$. In \eqref{eq:R12}, the first inequality follows from $D_x = \sup_{x,y \in \mathcal{X}} \| x-y\|$, the second inequality from Lemma~\ref{lemma:var bound}, and the last inequality from the sampling requirement \eqref{eq:sampling requirement}. 

We next bound $\mathcal{R}_2$. For $t=1,\dots, T$, replacing the function $f_t$ of Lemma~\ref{lemma:function variation} (in the Appendix) with $C_t$, we obtain 
\begin{align}\label{eq:R2}
 \mathcal{R}_{2}    & \le  2  \Delta_T\sum_{t=2}^T \sup_{x\in \mathcal{X}}|C_t(x)-C_{t-1}(x)| \nonumber \\
& =2  \Delta_T\sum_{t=2}^T\sup_{x\in \mathcal{X}} \bigg| \text{CVaR}_{\alpha_t}[J_t(x)] - \text{CVaR}_{\alpha_{t-1}}[J_{t-1}(x)] \bigg|\nonumber \\ 
& =2  \Delta_T\sum_{t=2}^T\sup_{x\in \mathcal{X}} \bigg| \text{CVaR}_{\alpha_t}[J_t(x)] - \text{CVaR}_{\alpha_{t-1}}[J_t(x)] 
\nonumber \\ 
&\hspace{1.5em}
+ \text{CVaR}_{\alpha_{t-1}}[J_t(x)] - \text{CVaR}_{\alpha_{t-1}}[J_{t-1}(x)] \bigg|
\nonumber \\ 
& \le \mathcal{R}_{21} + \mathcal{R}_{22},   
\end{align}
where 
\begin{align*}
\mathcal{R}_{21} &= 2\Delta_T\sum_{t=2}^T\sup_{x\in \mathcal{X}} \big| \text{CVaR}_{\alpha_t}[J_t(x)] - \text{CVaR}_{\alpha_{t-1}}[J_t(x)] \big|,    \nonumber \\ 
\mathcal{R}_{22} &= 2\Delta_T\sum_{t=2}^T\sup_{x\in \mathcal{X}} \big| \text{CVaR}_{\alpha_{t-1}}[J_t(x)] - \text{CVaR}_{\alpha_{t-1}}[J_{t-1}(x)] \big|.
\end{align*}
By Lemma~\ref{lemma:cvar-risk variation bound}, we have 
\begin{equation}\label{eq:R21}
\mathcal{R}_{21} \le 2 \Delta_T  \sum_{t=2}^T  U \bigg|\frac{1}{\alpha_t} -\frac{1}{\alpha_{t-1}}  \bigg|
\le \frac{2 U \Delta_T V_\alpha}{\alpha_{\min}^2} ,
\end{equation}
where $\alpha_{\min} := \min\{a_1,\dots,\alpha_T \}$, and the second inequality holds by Definition~\ref{def:risk-level variation}. 
Furthermore, by Lemma~\ref{lemma:cvar-function variation bound}, we have 
\begin{align}\label{eq:R22}
\mathcal{R}_{22} &\le   \sum_{t=2}^T\frac{2 \Delta_T}{\alpha_{t-1}}\sup_{x}\mathbb{E}_{\xi}\big[|J_t(x,\xi)-J_{t-1}(x,\xi)| \big]  \le  \frac{2 \Delta_TV_f}{\alpha_{\min}},
\end{align}
where the second inequality holds by Definition~\ref{def:function variation}. 
Substituting \eqref{eq:R1 1}--\eqref{eq:R22} into \eqref{eq:DR 01}, we obtain 
\begin{align}\label{eq:DR bound first-order}
 \mathrm{DR}(T) \le& \frac{D_x^2T}{ \eta\Delta_T }+\frac{\eta G^2T}{2}+ \frac{2 U \Delta_T V_\alpha}{\alpha_{\min}^2}  +  \frac{2 \Delta_TV_f}{\alpha_{\min}}\nonumber \\ 
 &+\frac{c D_x G L_g\sqrt{\ln{(2T/\gamma)}}}{\sqrt{2}\alpha_{\min} \underline{p} }  T^{1-\frac{a}{2}}
\end{align}
with probability at least $ 1- \gamma $.
We select $  \eta = \left(\frac{V_\alpha+V_f}{T}\right)^{\frac{1}{3}}$ and $\Delta_T = \left(\frac{T}{V_\alpha+V_f}\right)^{\frac{2}{3}} $ to minimize the regret bound. Then, ${\rm DR}(T) =  \tilde{\mathcal{O}}(T^{\frac{2}{3}}(V_\alpha+V_f)^{\frac{1}{3}}, T^{1-\frac{a}{2}}) $, which reduces to ${\rm DR}(T) =  \tilde{\mathcal{O}}(T^{\frac{2}{3}}(V_\alpha+V_f)^{\frac{1}{3}})$  when $a\ge \frac{2}{3}$, with probability at least $ 1- \gamma $.  \hfill $\qed

\label{lemma:smoothed cvar} \cite{cardoso2019risk} Given Assumptions~\ref{assumption:convex} and \ref{assumption:Lipschitz}, we have that  
\begin{enumerate}
    \item $C_t^\delta\left(x\right)$ is convex in $x$;
    \item
    $C_t^\delta (x)$ is $L_0$-Lipschitz in $x$ and $|C_t^\delta(x) - C_t(x)| \le \delta L_0 $.
\end{enumerate}

\label{lemma:cvar-estimation error bound} \cite{wang2022zeroth} Let $F$ and $G$ be the cumulative distribution functions of two random variables, respectively. Let the random variables be bounded by $U$. Then, we have that 
\begin{equation*} 
        |{\mathrm{CVaR}}_\alpha[F] -{\mathrm{CVaR}}_\alpha [G] | \le \frac{U}{\alpha} \sup_{x} |F(x)-G(x)|.
    \end{equation*}

\label{theorem:zeroth-order}
Let Assumptions \ref{assumption:convex} and \ref{assumption:Lipschitz} hold.  Suppose that the total sampling number over the horizon $T$ satisfy \eqref{eq:sampling requirement} with a constant $a>0$. 
\begin{enumerate}
    \item When $a \in (0,\frac{4}{5}]$, by selecting $  \delta =  T^{-\frac{a}{4}}(V_\alpha+V_f)^{\frac{1}{5}}$ and $\eta =T^{-\frac{3a}{4}}(V_\alpha+V_f)^{\frac{3}{5}}$,   
Algorithm~\ref{alg:zeroth-order}  achieves $\rm{DR}_0(T) =  \tilde{\mathcal{O}}(T^{1-\frac{a}{4}}(V_\alpha+V_f)^{\frac{1}{5}})$ with high probability.
 \item When $a >\frac{4}{5} $, by selecting  $  \delta =  T^{-\frac{1}{5}}(V_\alpha+V_f)^{\frac{1}{5}}$ and $\eta =T^{-\frac{3}{5}}(V_\alpha+V_f)^{\frac{3}{5}}$, Algorithm~\ref{alg:zeroth-order}  achieves $\rm{DR}_0(T) =  \tilde{\mathcal{O}}(T^{\frac{4}{5}}(V_\alpha+V_f)^{\frac{1}{5}}) $ with high probability.
\end{enumerate}

The dynamic regret \eqref{eq:dynamic regret definition 0} can be further written as 
\begin{align}\label{eq:convex 11}
\hspace{-0.5em}        \mathrm{DR}_0(T)  & =  \sum_{t=1}^T \mathbb{E}_{u}[C_t(\hat{x}_t+\delta u-\delta u)] - \mathbb{E}_{u}[C_t(x_t^\ast+\delta u-\delta u)]  \nonumber \\
&\leq \sum_{t=1}^T \Big(C_t^\delta( \hat{x}_t)-   C_t^\delta (x_t^\ast) \Big)+2 \delta L_0 T \nonumber \\ 
        &\leq \sum_{t=1}^T \Big(C_t^\delta( x_t)-  C_t^\delta (x_t^\ast)\Big)+3 \delta L_0 T,
\end{align}
where the first inequality follows from the Lipschitzness  of $C_t$ and the definition of $C_t^\delta$, as in \eqref{eq:smoothed cvar}. The second inequality follows from the Lipschitzness of $C_t^\delta$, as shown in Lemma \ref{lemma:smoothed cvar}. 
Furthermore, for $t=1,\dots,T$, we have 
\begin{align}\label{eq:projection mismatch}
   \min_{x_t \in \mathcal{X}^\delta} C_t^\delta(x_t) &=    \min_{x_t \in \mathcal{X}} C_t^\delta\big((1-\delta/r)x_t\big) \nonumber \\
   &\leq  \min_{x_t \in \mathcal{X}} (\delta/r) C_t^\delta(0) + (1-\delta/r)C_t^\delta(x_t) \nonumber \\
    &\leq \min_{x_t\in \mathcal{X}} C_t^\delta(x_t)+ (\delta/r)L_0 \left\|x_t \right\| \nonumber \\
   &\leq \min_{x_t\in \mathcal{X}} C_t^\delta(x_t)+D_x L_0 \delta/r,
\end{align}
where the first inequality follows from the convexity of $C_t^\delta$ and the second inequality from Lipschitzness of $C_t^\delta$, as shown in Lemma~\ref{lemma:smoothed cvar}.  Denote $x_t^{\delta,\ast} = {\textrm{argmin}}_{x \in \mathcal{X}^\delta} C_t^\delta (x)$ as the single-step optimal decision, for $t=1,\dots,T$. 
Substituting \eqref{eq:projection mismatch} into \eqref{eq:convex 11} and following the derivation of \eqref{eq:DR 01}, we have that 
\begin{align}\label{eq:convex 12}
\mathrm{DR}_0(T)  &\leq \sum_{t=1}^T C_t^\delta(x_t)-  \sum_{t=1}^T C_t^\delta (x_t^{\delta,\ast})+(3 +D_x/r)\delta L_0 T    \nonumber \\
&= \tilde{\mathcal{R}}_1 + \tilde{\mathcal{R}}_2 +(3 +D_x/r)\delta L_0 T  
\end{align}
with 
\begin{align*}
 \tilde{\mathcal{R}}_1 &= \sum_{j=1}^s\sum_{t\in \mathcal{T}_j}  \big(C_t^\delta(x_t)- C_t^\delta(\bar{\tilde{x}}_j^{\delta,\ast}) \big) \\
\tilde{\mathcal{R}}_2 &= \sum_{j=1}^s\sum_{t\in \mathcal{T}_j} \big( C_t^\delta(\bar{\tilde{x}}_j^{\delta,\ast}) - C_t^\delta(x_t^{\delta,\ast}) \big) 
\end{align*} and $\bar{\tilde{x}}_j^{\delta,\ast}=\min_{x\in\mathcal{X}^\delta}\sum_{t\in \mathcal{T}_j}C_t^\delta(x)$ is the optimal action over the interval $j$. 
From \eqref{eq:estimated gradient 0} and \eqref{eq:CVaR estimation error 0}, we have that \begin{equation}\label{eq:cvar derivative}
   \nabla C_t^\delta(x_t)   = \mathbb{E}\big[g_t^0 - \frac{d}{\delta}e_t^0u_t\big].
\end{equation}
Furthermore, for $\tilde{R}_1$,  we have that   
\begin{align}\label{eq:R1 zero}
\tilde{R}_1 &\le \sum_{j=1}^s\sum_{t\in \mathcal{T}_j}\left\langle \nabla C^\delta_t(x_t),x_t-\bar{\tilde{x}}_t^{\delta,\ast}   \right\rangle  \nonumber \\ 
& = \sum_{j=1}^s\sum_{t\in \mathcal{T}_j} \mathbb{E}\left[ \big\langle g_t^0 -\frac{d}{\delta}e_t^0u_t,x_t-\bar{\tilde{x}}_t^{\delta,\ast}   \big\rangle \right]
\nonumber \\ 
&\le \frac{D_x^2T}{ \eta\Delta_T }  + \tilde{\mathcal{R}}_{11} + \tilde{\mathcal{R}}_{12},    
\end{align}
with  $\tilde{\mathcal{R}}_{11} = \sum_{t=1}^T \frac{\eta}{2}\mathbb{E}[\|g_t^0\|^2]$, $    \tilde{\mathcal{R}}_{12} = \sum_{j=1}^s \sum_{t\in \mathcal{T}_j} \frac{d}{\delta}  \mathbb{E}[\| e_t^0\|\| x_t -\bar{\tilde{x}}_j^{\delta,\ast}\| ],$ where the first inequality follows from the convexity of $C_t^\delta$, the equality from substituting \eqref{eq:cvar derivative} into \eqref{eq:R1 zero}, and the second inequality follows the derivation of \eqref{eq:R1}-\eqref{eq:R1 1}. 
By the definition of the CVaR gradient estimate \eqref{eq:estimated gradient 0}, we have 
\begin{equation}\label{eq:R11 0}
 \tilde{\mathcal{R}}_{11} \le  \sum_{t=1}^T \frac{\eta}{2}  \left(\frac{d U}{\delta}\right)^2 = \frac{\eta d^2 U^2T}{2\delta^2}  .  
\end{equation}
We next bound $\tilde{\mathcal{R}}_{12}$. 
By the Dvoretzky–Kiefer–Wolfowitz (DKW) inequality \cite{dvoretzky1956asymptotic}, we have that 
\begin{equation}\label{eq:DKW 0}
    \mathbb{P}\left\{ \sup_{y} |\hat{F}_t^0(y) - F_t(y)| \ge \sqrt{\frac{\ln (2 / \bar{\gamma})}{2 n_t}}  \right\} \le  \bar{\gamma}.
\end{equation}
Denote the event in \eqref{eq:DKW 0} as $B_t$, and $\mathbb{P}\{B_t\}$ the occurrence probability of $B_t$, for $t=1,\dots, T$.
By  Lemma~\ref{lemma:cvar-estimation error bound} and the definition of $e_t^0$, as in \eqref{eq:CVaR estimation error 0}, we have 
\begin{align}
\label{eq:DKW cvar mismatch 0}
     |e_t^0 |  \le \frac{U}{\alpha_t}\sup_y\big| \hat{F}_t^0(y) - F_t(y)\big|  \le \frac{U}{\alpha_t} \sqrt{\frac{\ln (2 / \bar{\gamma})}{2 n_t}} 
\end{align}
with probability at least $1 -\bar{\gamma}$, for $t = 1,\dots, T$.  Let $\gamma = \bar{\gamma}T$. 
Then, subsituting \eqref{eq:DKW cvar mismatch 0} into $\tilde{\mathcal{R}}_{12}$, we obtain 
\begin{align}\label{eq:R12 0}
 \tilde{\mathcal{R}}_{12} &    \le  \sum_{t=1}^{T}\frac{dUD_x}{\delta \alpha_t} \sqrt{\frac{\ln (2T / \gamma)}{2 n_t}}    \le \frac{cdUD_x\sqrt{\ln (2T /  \gamma)}}{\sqrt{2}\delta \alpha_{\min}}  T^{1-\frac{a}{2}}.
\end{align}
with probability $1-\gamma$, which establishes as $    1 - \mathbb{P}\{\bigcup_{t=1}^{T} B_t \} \ge 1 - \sum_{t=1}^{T} \mathbb{P}\{B_t\} \ge 1 - T\frac{\gamma}{T} \ge 1-\gamma$.  The second inequality of \eqref{eq:R12 0} follows from the sampling requirement \eqref{eq:sampling requirement}. 
Furthermore, following the derivation of $\mathcal{R}_2$, as in \eqref{eq:R2}--\eqref{eq:R22}, we have 
\begin{equation}\label{eq:R2 0}
\tilde{R}_2 \le    \frac{2 U \Delta_T V_\alpha}{\alpha_{\min}^2}  +  \frac{2 \Delta_TV_f}{\alpha_{\min}}. 
\end{equation} 
Substituting \eqref{eq:R1 zero},  \eqref{eq:R11 0}, \eqref{eq:R12 0}, and \eqref{eq:R2 0} into \eqref{eq:convex 12}, we obtain 
\begin{align*}
\text{DR}_0(T) &\le (3 +D_x/r)\delta L_0 T + \frac{D_x^2T}{ \eta\Delta_T} + \frac{\eta d^2 U^2T}{2\delta^2} \nonumber \\ 
&\hspace{-3em}+ \frac{cdUD_x\sqrt{\ln (2T / \gamma)}}{\sqrt{2}\delta \alpha_{\min}}  T^{1-\frac{a}{2}} +  \frac{2 U \Delta_T V_\alpha}{\alpha_{\min}^2}+ \frac{2 \Delta_TV_f}{\alpha_{\min}}
\end{align*}
with probability $1-\gamma$. 
To minimize the regret $\text{DR}_0(T)$, we select $  \delta =  T^{-\frac{a}{4}}(V_\alpha+V_f)^{\frac{1}{5}}$, $\eta =T^{-\frac{3a}{4}}(V_\alpha+V_f)^{\frac{3}{5}}$, and $\Delta_T = T^{a}(V_\alpha+V_f)^{-\frac{4}{5}}$ when $a \in (0,\frac{4}{5}]$ and $  \delta =  T^{-\frac{1}{5}}(V_\alpha+V_f)^{\frac{1}{5}}$, $\eta =T^{-\frac{3}{5}}(V_\alpha+V_f)^{\frac{3}{5}}$, and $\Delta_T = T^{\frac{4}{5}}(V_\alpha+V_f)^{-\frac{4}{5}}$ when $a >\frac{4}{5} $. 
Hence,
$\text{DR}_0(T) =  \tilde{\mathcal{O}}(T^{1-\frac{a}{4}}(V_\alpha+V_f)^{\frac{1}{5}}) $ when $a\in(0,\frac{4}{5}]$ and $\text{DR}_0(T) =  \tilde{\mathcal{O}}(T^{\frac{4}{5}}(V_\alpha+V_f)^{\frac{1}{5}}) $ when $a > \frac{4}{5}$, with probability at least $ 1- \gamma $.
\hfill $\qed

\label{lemma:function variation}\cite{besbes2015non}
Consider the function $f_t(x): \mathcal{X} \rightarrow \mathbb{R}$, define the function sequences over iteration horizon $T$ as $\{f_t(x_t)\}_{t=1}^{T}$,  we have that
\begin{align*} 
    \sum_{j=1}^s   \sum\limits_{t \in \mathcal{T}_j}  \big(f_t(\tilde{x}_j^{\ast}) -  f_t(x_t^{\ast})\big)   \leq  2  \Delta_T \sum_{t=2}^T \sup_{x\in \mathcal{X}}|f_t(x)-f_{t-1}(x)|, 
\end{align*}  
where $\tilde{x}_j^\ast = \min_{x\in\mathcal{X}}\sum_{t\in\mathcal{T}_j}f_t(x)$ and $x_t^\ast = \min_{x\in\mathcal{X}}f_t(x)$.

Define the augmented functions 
\begin{align*}
    &L_{\alpha_1}(v) = v+\frac{1}{\alpha_1} \mathbb{E}_{X\sim \mathcal{D}_x}[J(X)-v]_{+} ,\\
    &L_{\alpha_2}(v) = v+\frac{1}{\alpha_2} \mathbb{E}_{X\sim \mathcal{D}_x}[J(X)-v]_{+}.
\end{align*}
As shown in \cite{rockafellar2000optimization}, we have
\begin{align*}    \mathop{{\text{CVaR}}_{\alpha_1}}[J(X)] =  \min\limits_{v}L_{\alpha_1}(v),  \ \mathop{{\text{CVaR}}_{\alpha_2}} [J(X)] = \min\limits_{v}L_{{\alpha_2}}(v).
\end{align*}
Let $v_{\alpha_1} = \text{argmin}_{v}L_{\alpha_1}(v)$ and $v_{\alpha_2} = \text{argmin}_{v}L_{\alpha_2}(v)$.
Then, we have
\begin{equation*}
    L_{\alpha_1}(v_{\alpha_1}) = \mathop{{\text{CVaR}}_{\alpha_1}}[J(X)], \ 
     L_{\alpha_2}(v_{\alpha_2}) = \mathop{{\text{CVaR}}_{\alpha_2}}[J(X)].
\end{equation*}
Furthermore, we have
\begin{flalign*}
  & \mathop{{\text{CVaR}}_{\alpha_1}} [J(X)]  -  \mathop{{\text{CVaR}}_{\alpha_2}} [J(X)] \nonumber \\
 =  &L_{\alpha_1}(v_{\alpha_1}) -L_{\alpha_2}(v_{\alpha_2}) \nonumber \\
  \leq & L_{\alpha_1}(v_{\alpha_2}) - L_{\alpha_2}(v_{\alpha_2}) \nonumber \\ 
  = & v_{\alpha_2} + \frac{1}{{\alpha_1}}\mathbb{E}_{X\sim \mathcal{D}_x}[J(X)-v_{\alpha_2}]_{+}  \nonumber \\
  &  -v_{\alpha_2} - \frac{1}{{\alpha_2}}\mathbb{E}_{X\sim \mathcal{D}_x} [J(X)-v_{\alpha_2}]_+ \nonumber \\
 =& \Big| \frac{1}{{\alpha_1}} - \frac{1}{\alpha_2}\Big| \mathbb{E}_{X\sim \mathcal{D}_x} [J(X)-v_{\alpha_2}]_{+}
 \le  \Big| \frac{1}{{\alpha_1}} - \frac{1}{\alpha_2} \Big|  U , &&
\end{flalign*}
where the first inequality follows from $v_{\alpha_1} = \text{argmin}_{v}L_{{\alpha_1}}(v)$ and $L_{\alpha_1}(v_{\alpha_1}) \le L_{\alpha_1}(v_{\alpha_2}) $, and the second inequality from $|J(\cdot)| \le U$.
